const ulContainer = document.querySelector('.gallery');


function markupGallery(array) {
    return array.map(element => `<li class="gallery-item">
  <a class="gallery-link" href="${element.original}">
    <img
      class="gallery-image"
      src= "${element.preview}"
      alt="${element.description}"
    />
  </a>
</li>`).join("");
}

ulContainer.insertAdjacentHTML('beforeend', markupGallery(images));

const gallery = new SimpleLightbox(".gallery-link", {
    captionsData: "alt" ,
    captionPosition: "bottom" ,
    captionDelay: 250, 
});

